const queryClient = new QueryClient();
const serviceNames: Record<string, string> = { couples: 'Couples therapy', individual: 'Individual therapy', child_teen: 'Child & teen support', christian_counseling: 'Christian counseling' };
const serviceDescription = (service: string) => `[Insert service description for ${serviceNames[service] ?? service}]`;
const fmtDate = (value?: string) => value ? new Date(value).toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' }) : 'Not scheduled';
const fmtTime = (value?: string) => value ? new Date(value).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' }) : '';
const titleCase = (value: string) => value.replaceAll('_', ' ').replace(/\b\w/g, (l) => l.toUpperCase());
const startOfWeek = () => {
  const value = new Date();
  const daysSinceMonday = (value.getDay() + 6) % 7;
  value.setDate(value.getDate() - daysSinceMonday);
  value.setHours(0, 0, 0, 0);
  return value;
};

function Button({ children, variant = 'primary', className = '', ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'quiet' | 'outline' | 'danger' }) {
  const variants = { primary: 'bg-primary text-primary-foreground hover:bg-primary/90', quiet: 'bg-muted text-foreground hover:bg-muted/70', outline: 'border border-border bg-transparent hover:bg-muted', danger: 'bg-destructive/10 text-destructive hover:bg-destructive/15' };
  return <button className={`button focus-ring inline-flex items-center justify-center gap-2 rounded-full px-4 py-2.5 text-sm font-semibold ${variants[variant]} ${className}`} {...props}>{children}</button>;
}
function Badge({ children, tone = 'sage' }: { children: ReactNode; tone?: 'sage' | 'sand' | 'blue' | 'red' | 'slate' }) {
  const tones = { sage: 'bg-primary/10 text-primary', sand: 'bg-accent/35 text-foreground', blue: 'bg-secondary/10 text-secondary', red: 'bg-destructive/10 text-destructive', slate: 'bg-muted text-muted-foreground' };
  return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-semibold tracking-wide ${tones[tone]}`}>{children}</span>;
}
function Card({ children, className = '' }: { children: ReactNode; className?: string }) { return <div className={`soft-card ${className}`}>{children}</div>; }
function Skeleton({ className = '' }: { className?: string }) { return <div className={`animate-pulse-soft rounded-lg bg-muted ${className}`} />; }
function LoadingState() { return <div className="grid gap-4 sm:grid-cols-2"><Skeleton className="h-28" /><Skeleton className="h-28" /><Skeleton className="h-64 sm:col-span-2" /></div>; }
function EmptyState({ title, copy, action }: { title: string; copy: string; action?: ReactNode }) { return <Card className="flex min-h-48 flex-col items-center justify-center p-8 text-center"><div className="mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-primary/10 text-primary"><Sparkles size={20} /></div><h3 className="display text-xl">{title}</h3><p className="mt-2 max-w-sm text-sm text-muted-foreground">{copy}</p>{action && <div className="mt-5">{action}</div>}</Card>; }
function PageTitle({ eyebrow, title, copy, action }: { eyebrow?: string; title: string; copy?: string; action?: ReactNode }) { return <div className="mb-8 flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between"><div><p className="mono text-[11px] uppercase tracking-[.2em] text-secondary">{eyebrow}</p><h1 className="display mt-2 text-4xl leading-tight text-foreground sm:text-5xl">{title}</h1>{copy && <p className="mt-3 max-w-2xl text-sm leading-6 text-muted-foreground">{copy}</p>}</div>{action}</div>; }
